import java.util.function.Supplier;
class Person {
  static final class RequestBuilder implements Supplier<String> {
    String build() {
      return "x";
    }
    @Override
    public String get() {
      return build();
    }
  }
  static final class QueryBuilder {
    String create() {
      return "x";
    }
  }
}
@lombok.Builder
class Request {
  private final String path;
  static final class RequestBuilder {
    Request build() {
      return new Request(path == null ? "/" : path);
    }
  }
  Request(String path) {
    this.path = path.trim();
  }
}
class Response {
  private final int status;
  @lombok.Builder
  Response(int status) {
    this.status = status + 0;
  }
  static final class ResponseBuilder {
    Response build() {
      return new Response(200);
    }
  }
}
